script.setup:
// p5.js in instance mode, without a canvas of its own: the sketch draws into an offscreen
// p5.Graphics (ink strokes following p5's Perlin noise), which the scene uploads as a texture
// every frame and shows on paper with a little grain.
const mod = await ctx.utils.import("https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.esm.min.js");
const P5 = mod.default ?? mod;
const p = await new Promise((resolve) => new P5((sk) => { sk.setup = () => { sk.noCanvas(); sk.noLoop(); resolve(sk); }; }));
const [w, h] = ctx.resolution, GH = 900, GW = Math.round((GH * w) / h);
const pg = p.createGraphics(GW, GH);
pg.pixelDensity(1);
pg.elt.style.display = "none";
pg.background(244, 238, 226);
const INKS = [[24, 34, 90], [214, 52, 40], [0, 128, 140], [240, 170, 20]];
const N = 900;
const agents = Array.from({ length: N }, (_, i) => ({ x: Math.random() * GW, y: Math.random() * GH, ink: INKS[i % INKS.length], life: Math.random() * 300 }));
const gl = ctx.gl, tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_ink; uniform vec2 u_resolution; uniform float u_grain;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
  vec3 c = texture(u_ink, vec2(v_uv.x, 1.0 - v_uv.y)).rgb;
  float g = hash(floor(v_uv * u_resolution / 1.5)) - 0.5;
  c += g * u_grain * 0.08;
  c *= 1.0 - 0.25 * pow(length(v_uv - 0.5) * 1.3, 2.5);
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, { p, pg, agents, GW, GH, tex, frame: 0,
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { p, pg, GW, GH } = s;
if (u.u_clear) pg.background(244, 238, 226);
// paper slowly reclaims old strokes
pg.noStroke(); pg.fill(244, 238, 226, u.u_fade * 255); pg.rect(0, 0, GW, GH);
const mx = ctx.mouse[0] * GW, my = ctx.mouse[1] * GH;
const z = ctx.time * 0.05 * u.u_flow, sc = 0.0016 * u.u_scale;
pg.strokeWeight(1.2);
const count = Math.min(s.agents.length, u.u_count | 0);
for (let i = 0; i < count; i++) {
  const a = s.agents[i];
  let ang = p.noise(a.x * sc, a.y * sc, z) * p.TWO_PI * 2.5;
  // the pointer swirls the strokes around it
  const dx = a.x - mx, dy = a.y - my, d2 = dx * dx + dy * dy;
  if (ctx.mouseDown || d2 < 20000) ang += (Math.atan2(dy, dx) + Math.PI / 2 - ang) * Math.exp(-d2 / 30000);
  const nx = a.x + Math.cos(ang) * 2.2, ny = a.y + Math.sin(ang) * 2.2;
  pg.stroke(a.ink[0], a.ink[1], a.ink[2], 90);
  pg.line(a.x, a.y, nx, ny);
  a.x = nx; a.y = ny; a.life -= 1;
  if (a.life < 0 || a.x < 0 || a.y < 0 || a.x > GW || a.y > GH) { a.x = Math.random() * GW; a.y = Math.random() * GH; a.life = 150 + Math.random() * 300; }
}
ctx.publish("strokes", count);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, pg.elt);
gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_ink", s.tex, 0);
ctx.utils.drawFullscreen(s.prog);
